import * as THREE from 'three/webgpu';
import { texture, uv, uniform, vec4, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-journal-card-3';

  const pos = config.scenePosition?.position ?? [3.2, -0.3, 0];
  const rot = config.scenePosition?.rotation ?? [0, 0, 0];
  const scl = config.scenePosition?.scale ?? [1, 1, 1];

  group.position.set(pos[0], pos[1], pos[2]);
  group.rotation.set(rot[0], rot[1], rot[2]);
  group.scale.set(scl[0], scl[1], scl[2]);

  const width = 1.6;
  const height = 1.0;
  const geometry = new THREE.PlaneGeometry(width, height);

  const imgUrl = '/prism-mock/home/nodes/cta-hero-isolated.png';
  const map = ctx.textureLoader(imgUrl);
  if (map) {
    map.colorSpace = THREE.SRGBColorSpace;
  }

  const hoverUniform = uniform(0.0);
  const focusUniform = uniform(0.0);

  const material = new THREE.MeshBasicNodeMaterial();
  material.transparent = true;

  const baseColor = map ? texture(map, uv()) : vec4(color(config.visualStyle?.colors?.surface ?? '#0b0b10'), 1.0);

  const accentColor = color(config.visualStyle?.colors?.accent ?? '#ff2a38');
  const edgeMix = focusUniform.mul(0.35);
  const finalColor = mix(baseColor, vec4(accentColor, 1.0), edgeMix);

  material.colorNode = finalColor;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'journal-card-3-plane';
  group.add(mesh);

  // Stock badge (data binding target) — simple colored indicator plane
  const badgeGeo = new THREE.PlaneGeometry(0.18, 0.09);
  const badgeMat = new THREE.MeshBasicNodeMaterial();
  badgeMat.transparent = true;
  const badgeUniform = uniform(new THREE.Color(0x888888));
  badgeMat.colorNode = vec4(badgeUniform, 1.0);
  const badgeMesh = new THREE.Mesh(badgeGeo, badgeMat);
  badgeMesh.position.set(width / 2 - 0.14, height / 2 - 0.1, 0.01);
  badgeMesh.name = 'stockBadge';
  group.add(badgeMesh);

  group.userData.setStockBadge = (inStock) => {
    badgeUniform.value.set(inStock ? 0x2ecc71 : 0xe74c3c);
  };

  // Timelines
  let hoverTl = null;
  let pressTl = null;

  const baseY = group.position.y;

  group.userData.handlers = {
    onPointerOver: () => {
      hoverTl?.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(group.position, {
        y: baseY + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
      hoverTl.to(hoverUniform, { value: 1.0, duration: 0.3 }, 0);
    },
    onPointerOut: () => {
      hoverTl?.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(group.position, {
        y: baseY,
        duration: 0.7,
        ease: 'power3.out',
      });
      hoverTl.to(hoverUniform, { value: 0.0, duration: 0.3 }, 0);
    },
    onPointerDown: () => {
      pressTl?.kill();
      pressTl = gsap.timeline();
      pressTl.to(group.scale, {
        x: scl[0] * 0.97,
        y: scl[1] * 0.97,
        z: scl[2] * 0.97,
        duration: 0.12,
        ease: 'back.out',
      });
    },
    onPointerUp: () => {
      pressTl?.kill();
      pressTl = gsap.timeline();
      pressTl.to(group.scale, {
        x: scl[0],
        y: scl[1],
        z: scl[2],
        duration: 0.12,
        ease: 'back.out',
      });
    },
    onFocus: () => {
      gsap.to(focusUniform, { value: 1.0, duration: 0.2 });
    },
    onBlur: () => {
      gsap.to(focusUniform, { value: 0.0, duration: 0.2 });
    },
    onClick: () => {
      if (group.userData.emit) {
        group.userData.emit('hub-journal.select', { nodeId: group.name });
      }
    },
  };

  // Apply cinematic primitives (none specified for this node)
  const primitivesList = config.cinematicPrimitives ?? [];
  for (const primitive of primitivesList) {
    if (ctx.primitives && ctx.primitives[primitive.name]) {
      ctx.primitives[primitive.name](group, primitive.params);
    }
  }

  group.userData.cleanup = () => {
    hoverTl?.kill();
    pressTl?.kill();
    geometry.dispose();
    badgeGeo.dispose();
    material.dispose();
    badgeMat.dispose();
    if (map) map.dispose();
  };

  return group;
}
